cat >> src/board.test.ts <<'EOF'

import { createBoard, type BoardErrorCode } from "./board";

function makeBoard(columns = [{ name: "Backlog" }, { name: "Doing" }, { name: "Review" }, { name: "Done" }]) {
  let time = 1_000;
  const clock = { set: (t: number) => { time = t; } };
  const board = createBoard({ columns, now: () => time });
  return { board, clock };
}

function expectCode(fn: () => unknown, code: BoardErrorCode) {
  try {
    fn();
  } catch (e) {
    expect(e).toBeInstanceOf(BoardError);
    expect((e as BoardError).code).toBe(code);
    return;
  }
  throw new Error(`expected BoardError ${code}`);
}

test("addCard puts C1 into the first column", () => {
  const { board } = makeBoard();
  expect(board.addCard("Fix login")).toBe("C1");
  expect(board.cardsIn("Backlog")).toEqual(["C1"]);
  expect(board.cardsIn("Doing")).toEqual([]);
});
EOF
bun test 2>&1 | tail -5

